#include "KS/SRC/ks/FEPanel_shared.h"

#define MAX_HINT_APPEARANCES 2

enum {
    BEACH_SEBASTIAN = 0,
    BEACH_MAVERICKS = 9,
    BEACH_TRESTLES = 6,
    BEACH_ANTARCTICA = 11,
    GT_HINT_STAND = 470
};

class game {
    char fields_before_num_ai_players[0xB4];
    int num_ai_players;
    int num_active_players;
    char fields_before_beach_id[0x16C];
    int beach_id;

public:
    int get_beach_id() const { return beach_id; }
    bool is_splitscreen(void) {
        return num_active_players > 1 && num_ai_players == 0;
    }
};

extern game *g_game_ptr;
extern stringx ksGlobalTextArray[];

class IGOHintManager {
    stringx hint_text;
    TextString *instruction_text;
    float current_hint_time;
    int current_hint;
    bool competition_help;
    int hint_use[15];

public:
    enum {
        StandUp,
        ObjectApproaching,
        CompetitionNeedFace,
        CompetitionNeedTube,
        CompetitionNeedAir,
        LandedSideways,
        SurfingBackwards,
        LostBalance,
        TooHighOnTubeWall,
        LandedDuringTrick,
        StoodTooFarOut,
        DidNotStand,
        TryPaddlingForward,
        HitTubeWall,
        SpunTooMuch,
        NUM_HINTS
    };

    void process_help_string(stringx &dest, const char *source);
    void SetHint(int new_hint);
};

__asm__(".equ g_game_ptr, 0x0046AC64");
__asm__(".equ ksGlobalTextArray, 0x003E6050");
__asm__(".equ process_help_string__14IGOHintManagerR7stringxPCc, 0x00164380");
__asm__(".equ __7stringxRC7stringx, 0x0034D4D0");

void IGOHintManager::SetHint(int new_hint)
{
	assert(new_hint < NUM_HINTS);
	int current_beach = g_game_ptr->get_beach_id();

	//  No hints in multiplayer.  the screen is too small for two sets of these.
	if (g_game_ptr->is_splitscreen ())
		return;

	//  Only show the stand up hint on the first beaches.
	if ((new_hint == StandUp || new_hint == ObjectApproaching) &&
		!(current_beach == BEACH_SEBASTIAN || current_beach == BEACH_MAVERICKS || 
		current_beach == BEACH_TRESTLES || current_beach == BEACH_ANTARCTICA))
		return;

	//  The "did not stand" message should change to a different message if this keeps happening.
	if (new_hint == DidNotStand && hint_use[new_hint] >= MAX_HINT_APPEARANCES)
		new_hint = TryPaddlingForward;

	//  Don't let the hint appear more than a few times.
	if (hint_use[new_hint] >= MAX_HINT_APPEARANCES)
		return;
	else
		hint_use[new_hint]++;

	//  Set the text to the new hint.
	process_help_string(hint_text, ksGlobalTextArray[GT_HINT_STAND + new_hint].c_str());
	instruction_text->changeText(hint_text);

	//  Make it visible
	instruction_text->SetFade(0.0);
	current_hint_time = 0.0f;
	current_hint = new_hint;
}
